// This file is @generated by perseid, vendored from the runtime of the CLI pack.
//! `--jq`: jq filters run with jaq, on `serde_json` values.
use jaq_core::{
    data::JustLut,
    load::{Arena, File, Loader},
    unwrap_valr, Compiler, Ctx, Vars,
};
use jaq_json::Val;
use serde::Deserialize;
use serde_json::{Map, Number, Value};

use super::error::CliError;

/// jq's `@csv` and `@tsv`, which jaq lacks.
const DEFS: &str = r#"
def @csv: map(if type == "string" then "\"" + gsub("\""; "\"\"") + "\"" elif . == null then "" else tostring end) | join(",");
def @tsv: map(if type == "string" then gsub("\\\\"; "\\\\") | gsub("\t"; "\\t") | gsub("\n"; "\\n") | gsub("\r"; "\\r") elif . == null then "" else tostring end) | join("\t");
"#;

/// A compiled filter, run once per document.
pub struct Jq {
    filter: jaq_core::Filter<JustLut<Val>>,
}

impl Jq {
    /// Compiles `code` with jq's standard library; errors name the `--jq` flag.
    pub fn compile(code: &str) -> Result<Self, CliError> {
        let defs = jaq_core::defs()
            .chain(jaq_std::defs())
            .chain(jaq_json::defs())
            .chain(jaq_core::load::parse(DEFS, |p| p.defs()).unwrap_or_default());
        let funs = jaq_core::funs()
            .chain(jaq_std::funs())
            .chain(jaq_json::funs());
        let arena = Arena::default();
        let program = File { code, path: () };
        let modules = Loader::new(defs).load(&arena, program).map_err(|errors| {
            let reasons = errors
                .into_iter()
                .flat_map(|(_, error)| load_reasons(code, error));
            invalid(reasons.collect())
        })?;
        let filter = Compiler::default()
            .with_funs(funs)
            .compile(modules)
            .map_err(|errors| {
                let reasons = errors.into_iter().flat_map(|(_, undefined)| {
                    undefined
                        .into_iter()
                        .map(|(name, kind)| format!("undefined {} `{name}`", kind.as_str()))
                });
                invalid(reasons.collect())
            })?;
        Ok(Self { filter })
    }

    /// Every output of the filter on `input`.
    pub fn run(&self, input: &Value) -> Result<Vec<Value>, CliError> {
        let input = Val::deserialize(input).map_err(|e| CliError::internal(e.to_string()))?;
        let ctx = Ctx::<JustLut<Val>>::new(&self.filter.lut, Vars::new([]));
        self.filter
            .id
            .run((ctx, input))
            .map(unwrap_valr)
            .map(|output| match output {
                Ok(val) => Ok(to_json(val)),
                Err(error) => Err(CliError::usage(format!("--jq: {error}"))),
            })
            .collect()
    }
}

fn invalid(reasons: Vec<String>) -> CliError {
    CliError::usage(format!("--jq: invalid filter: {}", reasons.join("; ")))
}

fn load_reasons(code: &str, error: jaq_core::load::Error<&str>) -> Vec<String> {
    let at = |rest: &str| {
        let offset = (rest.as_ptr() as usize).saturating_sub(code.as_ptr() as usize);
        format!(
            "at character {}",
            code[..offset.min(code.len())].chars().count() + 1
        )
    };
    use jaq_core::load::Error;
    match error {
        Error::Io(errors) => errors
            .into_iter()
            .map(|(path, e)| format!("{path}: {e}"))
            .collect(),
        Error::Lex(errors) => errors
            .into_iter()
            .map(|(expect, rest)| format!("expected {} {}", expect.as_str(), at(rest)))
            .collect(),
        Error::Parse(errors) => errors
            .into_iter()
            .map(|(expect, rest)| match rest.trim() {
                "" => format!("expected {} at the end", expect.as_str()),
                found => format!("expected {} {}, found `{found}`", expect.as_str(), at(rest)),
            })
            .collect(),
    }
}

fn to_json(val: Val) -> Value {
    match val {
        Val::Null => Value::Null,
        Val::Bool(b) => Value::Bool(b),
        Val::Num(num) => number(&num.to_string()),
        Val::TStr(bytes) | Val::BStr(bytes) => {
            Value::String(String::from_utf8_lossy(&bytes).into_owned())
        }
        Val::Arr(items) => Value::Array(items.iter().cloned().map(to_json).collect()),
        Val::Obj(map) => Value::Object(
            map.iter()
                .map(|(key, value)| (key_string(key), to_json(value.clone())))
                .collect::<Map<_, _>>(),
        ),
    }
}

fn number(text: &str) -> Value {
    if let Ok(int) = text.parse::<i64>() {
        return Value::Number(int.into());
    }
    if let Ok(int) = text.parse::<u64>() {
        return Value::Number(int.into());
    }
    text.parse::<f64>()
        .ok()
        .and_then(Number::from_f64)
        .map_or(Value::Null, Value::Number)
}

fn key_string(key: &Val) -> String {
    match key {
        Val::TStr(bytes) | Val::BStr(bytes) => String::from_utf8_lossy(bytes).into_owned(),
        other => other.to_string(),
    }
}

#[cfg(test)]
mod tests {
    use serde_json::json;

    use super::*;

    fn run(code: &str, input: Value) -> Vec<Value> {
        Jq::compile(code).unwrap().run(&input).unwrap()
    }

    #[test]
    fn filters_select_and_build_values() {
        let things = json!([{"id": "th_1", "n": 3}, {"id": "th_2", "n": 10}]);
        assert_eq!(
            run(".[].id", things.clone()),
            [json!("th_1"), json!("th_2")]
        );
        assert_eq!(
            run("map(select(.n > 5)) | length", things.clone()),
            [json!(1)]
        );
        assert_eq!(run("[.[].n] | add / 2", things.clone()), [json!(6.5)]);
        assert_eq!(
            run("{b: 1, a: .[0].id}", things),
            [json!({"b": 1, "a": "th_1"})]
        );
    }

    #[test]
    fn object_key_order_survives_the_round_trip() {
        let out = run(".", json!({"z": 1, "a": {"y": 2, "b": 3}}));
        assert_eq!(
            serde_json::to_string(&out[0]).unwrap(),
            r#"{"z":1,"a":{"y":2,"b":3}}"#
        );
    }

    #[test]
    fn standard_library_is_available() {
        let out = run(
            r#"[.[] | ascii_upcase] | join(",") | test("A,B")"#,
            json!(["a", "b"]),
        );
        assert_eq!(out, [json!(true)]);
        assert_eq!(run("keys", json!({"b": 1, "a": 2})), [json!(["a", "b"])]);
    }

    #[test]
    fn csv_and_tsv_rows() {
        let row = json!(["a\"b", 1, null, true, "t\tn\\"]);
        assert_eq!(
            run("@csv", row.clone()),
            [json!("\"a\"\"b\",1,,true,\"t\tn\\\"")]
        );
        assert_eq!(run("@tsv", row), [json!("a\"b\t1\t\ttrue\tt\\tn\\\\")]);
    }

    #[test]
    fn invalid_filters_are_usage_errors() {
        let error = Jq::compile(".[").err().unwrap();
        assert_eq!(error.exit_code(), super::super::error::exit::USAGE);
        assert!(
            error.message().starts_with("--jq: invalid filter: "),
            "{error}"
        );
        let undefined = Jq::compile("nosuchfn").err().unwrap();
        assert_eq!(
            undefined.message(),
            "--jq: invalid filter: undefined filter `nosuchfn`"
        );
    }

    #[test]
    fn runtime_errors_name_the_flag() {
        let error = Jq::compile(".a").unwrap().run(&json!([1])).err().unwrap();
        assert!(error.message().starts_with("--jq: "), "{error}");
    }
}
